INSERT INTO zhishi_notices (id, real, source, publish_date, title, event, audience, deadline, countdown, materials, entry, confidence, priority, points, digest_one, digest_points, raw, url, site, unit, src_generated_at) VALUES ('ahau-023', TRUE, '经济管理学院', '2025-06-19', '经济管理学院纪委召开工作会本网讯 6月18日下午，经济管理学院纪委在经管楼302会议室召开工作会。院纪委全体委员参加会议', '校内通知', NULL, NULL, NULL, NULL, NULL, 0.5, 'medium', '[{"text": "本网讯 6月18日下午，经济管理学院纪委在经管楼302会议室召开工作会", "quote": "本网讯 6月18日下午，经济管理学院纪委在经管楼302会议室召开工作会"}]'::jsonb, '校内通知：经济管理学院纪委召开工作会本网讯 6月18日下午，经济管理学院纪委在经管楼302', '[{"text": "本网讯 6月18日下午，经济管理学院纪委在经管楼302会议室召开工作会", "quote": "本网讯 6月18日下午，经济管理学院纪委在经管楼302会议室召开工作会"}]'::jsonb, '本网讯 6月18日下午，经济管理学院纪委在经管楼302会议室召开工作会。院纪委全体委员参加会议，会议由学院党委副书记、纪委书记周涛主持。 会议集体学习了习近平总书记在《求是》杂志发表的重要文章《加快建设教育强国》，习近平总书记致信祝贺复旦大学建校120周年贺信精神，中共中央政治局常委、中央纪委书记李希在二十届中央纪委常委会第十六次（扩大）集体学习时的讲话精神，省委常委、省纪委书记刘海泉在省纪委常委会会议时的讲话精神，学校纪检监察工作“三化”建设年行动业务培训班会议精神以及《纪检监察干部“八小时外”管理监督办法》等文', 'https://jgxy.ahau.edu.cn/info/1101/21666.htm', '经济管理学院 · 工作动态', 'jgxy', '2026-11-04 13:33:17') ON CONFLICT (id) DO UPDATE SET source=EXCLUDED.source, publish_date=EXCLUDED.publish_date, title=EXCLUDED.title, event=EXCLUDED.event, deadline=EXCLUDED.deadline, points=EXCLUDED.points, digest_one=EXCLUDED.digest_one, digest_points=EXCLUDED.digest_points, raw=EXCLUDED.raw, url=EXCLUDED.url, site=EXCLUDED.site, unit=EXCLUDED.unit, src_generated_at=EXCLUDED.src_generated_at